int countingValleys(int n, std::string s) {
    int count = 0;
    int level = 0;
    for (char c : s) {
        if (c == 'U') {
            level += 1;
            if (level == 0) {
                count += 1;
            }
        } else {
            level -= 1;
        }
    }
    return count;
