#include <iostream>
#include <vector>
#include <cmath>

int diagonalDifference(std::vector<std::vector<int>> arr) {
    int primaryDiagonalSum = 0;
    int secondaryDiagonalSum = 0;
    int size = arr.size();

    for (int i = 0; i < size; i++) {
        primaryDiagonalSum += arr[i][i];
        secondaryDiagonalSum += arr[i][size - i - 1];
    }

    int difference = std::abs(primaryDiagonalSum - secondaryDiagonalSum);
    return difference;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<std::vector<int>> arr(n, std::vector<int>(n));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            std::cin >> arr[i][j];
        }
    }

    int result = diagonalDifference(arr);
    std::cout << result << std::endl;

    return 0;
}
